// Round constants: RCON[i] is the value of x^(i-1) in GF(2^8) placed in the
// first byte of a round word during key expansion. Index 0 is unused so that
// RCON[round] maps directly to the key-schedule round number.
export const RCON = new Uint8Array([
  0x00, 0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1b, 0x36,
]);

// aes-core.mjs
//
// Low-level AES (FIPS-197) primitives implemented from scratch:
//   - key expansion for AES-128, AES-192 and AES-256
//   - single-block encryption and decryption
//
// All state is handled as 16-byte Uint8Arrays in the FIPS-197 column-major
// layout: state row r, column c lives at index 4*c + r, matching the natural
// byte order of the input/output blocks.

import { SBOX, INV_SBOX, RCON } from './aes-tables.mjs';

export const BLOCK_SIZE = 16;

// Number of rounds for a given number of 32-bit key words (Nk).
function roundsForNk(nk) {
  return nk + 6;
}

// Multiplication by 2 ({02}) in GF(2^8) with the AES reduction polynomial.
function xtime(a) {
  a &= 0xff;
  return ((a << 1) ^ (a & 0x80 ? 0x1b : 0x00)) & 0xff;
}

// General multiplication in GF(2^8) (Russian peasant multiplication),
// used by the inverse MixColumns step for the {09}, {0b}, {0d}, {0e} factors.
function gmul(a, b) {
  let result = 0;
  a &= 0xff;
  b &= 0xff;
  while (b !== 0) {
    if (b & 1) result ^= a;
    a = xtime(a);
    b >>>= 1;
  }
  return result & 0xff;
}

// Expand a cipher key into the full round-key schedule.
//
// key must be a Uint8Array of 16, 24 or 32 bytes. Returns a Uint8Array of
// 16 * (Nr + 1) bytes holding the round keys concatenated in round order.
// Throws RangeError on an invalid key length.
export function expandKey(key) {
  if (!(key instanceof Uint8Array)) {
    throw new TypeError('AES key must be a Uint8Array');
  }
  const nk = key.length / 4;
  if (nk !== 4 && nk !== 6 && nk !== 8) {
    throw new RangeError(
      `AES key must be 16, 24 or 32 bytes long, got ${key.length}`
    );
  }
  const nr = roundsForNk(nk);
  const totalWords = 4 * (nr + 1);

  // Work on 32-bit words; the expanded key is converted to bytes at the end.
  const w = new Uint32Array(totalWords);
  for (let i = 0; i < nk; i++) {
    w[i] =
      ((key[4 * i] << 24) |
        (key[4 * i + 1] << 16) |
        (key[4 * i + 2] << 8) |
        key[4 * i + 3]) >>>
      0;
  }

  for (let i = nk; i < totalWords; i++) {
    let temp = w[i - 1];
    if (i % nk === 0) {
      // RotWord, then SubWord, then XOR the round constant.
      temp =
        ((SBOX[(temp >>> 16) & 0xff] << 24) |
          (SBOX[(temp >>> 8) & 0xff] << 16) |
          (SBOX[temp & 0xff] << 8) |
          SBOX[(temp >>> 24) & 0xff]) >>>
        0;
      temp = (temp ^ (RCON[i / nk] << 24)) >>> 0;
    } else if (nk > 6 && i % nk === 4) {
      // AES-256 applies SubWord at this extra position.
      temp =
        ((SBOX[(temp >>> 24) & 0xff] << 24) |
          (SBOX[(temp >>> 16) & 0xff] << 16) |
          (SBOX[(temp >>> 8) & 0xff] << 8) |
          SBOX[temp & 0xff]) >>>
        0;
    }
    w[i] = (w[i - nk] ^ temp) >>> 0;
  }

  const schedule = new Uint8Array(16 * (nr + 1));
  for (let i = 0; i < totalWords; i++) {
    schedule[4 * i] = (w[i] >>> 24) & 0xff;
    schedule[4 * i + 1] = (w[i] >>> 16) & 0xff;
    schedule[4 * i + 2] = (w[i] >>> 8) & 0xff;
    schedule[4 * i + 3] = w[i] & 0xff;
  }
  return schedule;
}

// XOR the round key for the given round into the state.
function addRoundKey(state, schedule, round) {
  const offset = 16 * round;
  for (let i = 0; i < BLOCK_SIZE; i++) {
    state[i] ^= schedule[offset + i];
  }
}

function subBytes(state) {
  for (let i = 0; i < BLOCK_SIZE; i++) {
    state[i] = SBOX[state[i]];
  }
}

function invSubBytes(state) {
  for (let i = 0; i < BLOCK_SIZE; i++) {
    state[i] = INV_SBOX[state[i]];
  }
}

// Cyclically shift row r left by r bytes (state[4*c + r] layout).
function shiftRows(state) {
  const t = new Uint8Array(BLOCK_SIZE);
  for (let r = 0; r < 4; r++) {
    for (let c = 0; c < 4; c++) {
      t[4 * c + r] = state[4 * ((c + r) % 4) + r];
    }
  }
  state.set(t);
}

// Inverse of shiftRows: row r is cyclically shifted right by r bytes.
function invShiftRows(state) {
  const t = new Uint8Array(BLOCK_SIZE);
  for (let r = 0; r < 4; r++) {
    for (let c = 0; c < 4; c++) {
      t[4 * c + r] = state[4 * ((c - r + 4) % 4) + r];
    }
  }
  state.set(t);
}

// Mix each column with the fixed polynomial {03}x^3 + {01}x^2 + {01}x + {02}.
function mixColumns(state) {
  for (let c = 0; c < 4; c++) {
    const i = 4 * c;
    const a0 = state[i];
    const a1 = state[i + 1];
    const a2 = state[i + 2];
    const a3 = state[i + 3];
    state[i] = xtime(a0) ^ (xtime(a1) ^ a1) ^ a2 ^ a3;
    state[i + 1] = a0 ^ xtime(a1) ^ (xtime(a2) ^ a2) ^ a3;
    state[i + 2] = a0 ^ a1 ^ xtime(a2) ^ (xtime(a3) ^ a3);
    state[i + 3] = (xtime(a0) ^ a0) ^ a1 ^ a2 ^ xtime(a3);
  }
}

// Inverse MixColumns with coefficients {0e}, {0b}, {0d}, {09}.
function invMixColumns(state) {
  for (let c = 0; c < 4; c++) {
    const i = 4 * c;
    const a0 = state[i];
    const a1 = state[i + 1];
    const a2 = state[i + 2];
    const a3 = state[i + 3];
    state[i] = gmul(a0, 0x0e) ^ gmul(a1, 0x0b) ^ gmul(a2, 0x0d) ^ gmul(a3, 0x09);
    state[i + 1] = gmul(a0, 0x09) ^ gmul(a1, 0x0e) ^ gmul(a2, 0x0b) ^ gmul(a3, 0x0d);
    state[i + 2] = gmul(a0, 0x0d) ^ gmul(a1, 0x09) ^ gmul(a2, 0x0e) ^ gmul(a3, 0x0b);
    state[i + 3] = gmul(a0, 0x0b) ^ gmul(a1, 0x0d) ^ gmul(a2, 0x09) ^ gmul(a3, 0x0e);
  }
}

function checkBlock(block, what) {
  if (!(block instanceof Uint8Array)) {
    throw new TypeError(`${what} must be a Uint8Array`);
  }
  if (block.length !== BLOCK_SIZE) {
    throw new RangeError(
      `${what} must be exactly ${BLOCK_SIZE} bytes, got ${block.length}`
    );
  }
}

// Encrypt one 16-byte block with an expanded key schedule produced by
// expandKey(). Returns a new Uint8Array(16); the input is not modified.
export function encryptBlock(block, schedule) {
  checkBlock(block, 'AES block');
  const nr = schedule.length / BLOCK_SIZE - 1;
  const state = Uint8Array.from(block);

  addRoundKey(state, schedule, 0);
  for (let round = 1; round < nr; round++) {
    subBytes(state);
    shiftRows(state);
    mixColumns(state);
    addRoundKey(state, schedule, round);
  }
  // Final round omits MixColumns.
  subBytes(state);
  shiftRows(state);
  addRoundKey(state, schedule, nr);
  return state;
}

// Decrypt one 16-byte block with an expanded key schedule produced by
// expandKey(). Returns a new Uint8Array(16); the input is not modified.
export function decryptBlock(block, schedule) {
  checkBlock(block, 'AES block');
  const nr = schedule.length / BLOCK_SIZE - 1;
  const state = Uint8Array.from(block);

  addRoundKey(state, schedule, nr);
  for (let round = nr - 1; round >= 1; round--) {
    invShiftRows(state);
    invSubBytes(state);
    addRoundKey(state, schedule, round);
    invMixColumns(state);
  }
  // Final round omits the inverse MixColumns.
  invShiftRows(state);
  invSubBytes(state);
  addRoundKey(state, schedule, 0);
  return state;
}

// aes-ecb.mjs
//
// ECB (Electronic Codebook) mode wrapper around the raw AES block cipher in
// aes-core.mjs. Mirrors the pyaes API: the instance is constructed with the
// key once, then encrypt()/decrypt() may be called repeatedly on data whose
// length is a multiple of the 16-byte block size. No padding is applied.

import { BLOCK_SIZE, expandKey, encryptBlock, decryptBlock } from './aes-core.mjs';

export class AESModeOfOperationECB {
  // key must be a Uint8Array of 16 (AES-128), 24 (AES-192) or 32 (AES-256)
  // bytes. Throws RangeError on an invalid key length.
  constructor(key) {
    if (!(key instanceof Uint8Array)) {
      throw new TypeError('key must be a Uint8Array');
    }
    // expandKey performs the 16/24/32 length validation (RangeError).
    this._schedule = expandKey(key);
    this._keyLength = key.length;
  }

  // Encrypt data (Uint8Array, length a multiple of 16) under ECB mode.
  // Returns a new Uint8Array of the same length.
  encrypt(data) {
    this._checkData(data);
    const out = new Uint8Array(data.length);
    for (let offset = 0; offset < data.length; offset += BLOCK_SIZE) {
      out.set(
        encryptBlock(data.subarray(offset, offset + BLOCK_SIZE), this._schedule),
        offset
      );
    }
    return out;
  }

  // Decrypt data (Uint8Array, length a multiple of 16) under ECB mode.
  // Returns a new Uint8Array of the same length.
  decrypt(data) {
    this._checkData(data);
    const out = new Uint8Array(data.length);
    for (let offset = 0; offset < data.length; offset += BLOCK_SIZE) {
      out.set(
        decryptBlock(data.subarray(offset, offset + BLOCK_SIZE), this._schedule),
        offset
      );
    }
    return out;
  }

  _checkData(data) {
    if (!(data instanceof Uint8Array)) {
      throw new TypeError('data must be a Uint8Array');
    }
    if (data.length % BLOCK_SIZE !== 0) {
      throw new RangeError(
        `data length must be a multiple of ${BLOCK_SIZE} bytes, got ${data.length}`
      );
    }
  }
}

