import { AESModeOfOperationECB } from './lib/aes-ecb.mjs';

const hex = (u8) => [...u8].map(b => b.toString(16).padStart(2, '0')).join('');
const fromHex = (h) => Uint8Array.from(h.match(/../g).map(x => parseInt(x, 16)));
let pass = 0, fail = 0;
const check = (name, got, want) => {
  if (got === want) { pass++; }
  else { fail++; console.log(`FAIL ${name}\n  got  ${got}\n  want ${want}`); }
};

// FIPS-197 Appendix B/C known-answer vectors
const fips = [
  ['000102030405060708090a0b0c0d0e0f', '00112233445566778899aabbccddeeff', '69c4e0d86a7b0430d8cdb78070b4c55a'],
  ['000102030405060708090a0b0c0d0e0f1011121314151617', '00112233445566778899aabbccddeeff', 'dda97ca4864cdfe06eaf70a0ec0d7191'],
  ['000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f', '00112233445566778899aabbccddeeff', '8ea2b7ca516745bfeafc49904b496089'],
];
for (const [k, p, c] of fips) {
  const aes = new AESModeOfOperationECB(fromHex(k));
  check(`enc ${k.length*4}b`, hex(aes.encrypt(fromHex(p))), c);
  check(`dec ${k.length*4}b`, hex(aes.decrypt(fromHex(c))), p);
}

// Sample vector from test13.py
const key = new TextEncoder().encode('yPcJ.h9oOX7e5!cV');
const data = new TextEncoder().encode('=b=M1F[g)],C0CZ6');
const aes = new AESModeOfOperationECB(key);
const ct = aes.encrypt(data);
check('sample ciphertext', hex(ct), 'b79c38402fabc638cf040adecd3ce8109');
check('sample roundtrip', new TextDecoder().decode(aes.decrypt(ct)), '=b=M1F[g)],C0CZ6');

// Multi-block ECB + no-input-mutation
const aes2 = new AESModeOfOperationECB(key);
const two = aes.encrypt(data).length ? Uint8Array.from([...data, ...data]) : null;
const ct2 = aes2.encrypt(two);
check('ecb block independence', hex(ct2.subarray(0,16)), hex(ct2.subarray(16,32)));

// Error contract
const throwsRange = (fn) => { try { fn(); return false; } catch (e) { return e instanceof RangeError; } };
check('bad key len -> RangeError', throwsRange(() => new AESModeOfOperationECB(new Uint8Array(15))), true);
check('bad key len 20 -> RangeError', throwsRange(() => new AESModeOfOperationECB(new Uint8Array(20))), true);
check('bad data len -> RangeError', throwsRange(() => aes.encrypt(new Uint8Array(17))), true);
check('bad decrypt len -> RangeError', throwsRange(() => aes.decrypt(new Uint8Array(8))), true);
check('empty data ok', aes.encrypt(new Uint8Array(0)).length, 0);

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
EOF

